const $=id=>document.getElementById(id), key='dalia-english-preview-v1';let state={};try{state=JSON.parse(localStorage.getItem(key)||'{}')}catch{};if(!state||typeof state!=='object'||Array.isArray(state))state={};state=Object.assign(Object.create(null),Object.fromEntries(Object.entries(state).filter(([k,v])=>v&&typeof v==='object'&&!Array.isArray(v)).map(([k,v])=>[k,{n:Math.max(0,Math.min(3,Number(v.n)||0)),fav:v.fav===true,due:Number.isFinite(v.due)?Math.max(0,v.due):0}])));const customKey='dalia-english-custom-v1';let custom=[];try{custom=JSON.parse(localStorage.getItem(customKey)||'[]');if(!Array.isArray(custom))custom=[]}catch{};custom=custom.filter(w=>Array.isArray(w)&&w.length===5&&w.every(x=>typeof x==='string')&&['A1','A2','B1','B2','C1','C2'].includes(w[0])&&w[1].trim()&&w[2].trim());{let seen=new Set(words.map(w=>w[1].toLowerCase()));custom=custom.filter(w=>{let k=w[1].toLowerCase();if(seen.has(k))return false;seen.add(k);return true})}words.push(...custom);let dueOnly=false;let practiceLevels=new Set(['A1','A2','B1','B2','C1','C2']);try{let saved=JSON.parse(localStorage.getItem('dalia-english-practice-levels'));if(Array.isArray(saved))practiceLevels=new Set(saved.filter(x=>['A1','A2','B1','B2','C1','C2'].includes(x)))}catch{};let level='all',collection='',mode='meaning',current=null,previous=null,hinted=false,locked=false;
